import { TEXTURES } from "../config/constants";
import type { ProjectileAppearance } from "./projectiles";

export type SkinType = "character" | "vehicle";

export interface FirePose {
  textureKey: string;
  durationMs: number;
}

/** Idle animation played in a loop (frames already generated by the Preloader). */
export interface IdleAnimation {
  key: string;
  frameKeys: readonly string[];
  frameRate: number;
}

/**
 * Sheet following the templates in docs/sprite-templates: square frames, with
 * the feet (or the bottom of the ship) on the last pixel row of each frame.
 * Frames are numbered from 0, left to right then top to bottom (row, column
 * or grid). Textures and the animation are generated by the Preloader from
 * this information.
 */
export interface SpriteStrip {
  path: string;
  frameSize: number;
  /** Frames looped while idle, in order (e.g. thruster flames). */
  idle: readonly number[];
  /** Frame shown briefly on each shot (optional). */
  fire?: number;
  /** Frames per second of the idle animation. */
  frameRate?: number;
}

/** Appearance of a fighter, usable by a player skin or an opponent. */
export interface SpriteVisual {
  id: string;
  textureKey: string;
  firePose?: FirePose;
  idleAnimation?: IdleAnimation;
  strip?: SpriteStrip;
  /** Look of its projectiles, if different from the default one of the character. */
  projectileAppearance?: ProjectileAppearance;
}

/** A skin is purely visual: it never changes any combat stat. */
export interface SkinConfig extends SpriteVisual {
  name: string;
  description: string;
  type: SkinType;
  accentColor: string;
}

export const DEFAULT_SKIN_ID = "ship";

export const getStripSourceKey = (visualId: string): string =>
  `${visualId}-strip`;
export const getStripFrameKey = (visualId: string, index: number): string =>
  `${visualId}-frame-${index}`;

const DEFAULT_STRIP_FRAME_RATE = 6;
const FIRE_POSE_DURATION_MS = 160;

/** Appearance (textures, fire pose, animation) of a sprite drawn on a template sheet. */
export const createStripVisual = (
  id: string,
  strip: SpriteStrip,
): SpriteVisual => {
  const frameKeys = strip.idle.map((index) => getStripFrameKey(id, index));

  return {
    id,
    textureKey: frameKeys[0],
    firePose:
      strip.fire === undefined
        ? undefined
        : {
            textureKey: getStripFrameKey(id, strip.fire),
            durationMs: FIRE_POSE_DURATION_MS,
          },
    idleAnimation:
      frameKeys.length > 1
        ? {
            key: `${id}-idle`,
            frameKeys,
            frameRate: strip.frameRate ?? DEFAULT_STRIP_FRAME_RATE,
          }
        : undefined,
    strip,
  };
};

