export const SKIN_IDS: readonly string[] = SKINS.map((skin) => skin.id);

export const getSkinById = (id: string): SkinConfig => {
  return SKINS.find((skin) => skin.id === id) ?? SKINS[0];
};

export const getSkinTypeLabel = (skin: SkinConfig): string => {
  return skin.type === "character" ? "CHARACTER" : "VEHICLE";
};
